WITH paqrdt AS (  SELECT tab_paqa.PAQA_ID,  tab_paqa.PART_ID,  tab_paqa.PQRA_ID,  tab_paqa.PLNT_ID,  tab_paqa.CPLT_ID,  tab_oidx.INDEX,    tab_oidx.USER_ID,  tab_pqra.SQMS_PROFILE_NAME AS role_name,  tab_pers.last_name || ','|| tab_pers.first_name AS user_name    FROM S0NCSTR.S0NRP50D036        AS tab_paqa  INNER JOIN S0NCSTR.S0NRP50M085 AS tab_pqra  ON tab_paqa.PQRA_ID = tab_pqra.PQRA_ID  LEFT OUTER JOIN S0NCSTR.S0NRP50D010 AS tab_oidx  ON     tab_paqa.OIDX_ID = tab_oidx.OIDX_ID  LEFT OUTER JOIN S0SCSQMS.S0SRP75M001 AS tab_pers  ON    tab_oidx.USER_ID = tab_pers.user_id  WHERE tab_paqa.is_current_record = 'Y'   ) , pjpa AS (  SELECT             tab_pjpa.pjpr_pjpr_id AS pjpa_id,           tab_pjpa.pjpr_version_count AS version_count,           tab_pjpa.pppa_part_id AS pppa_part_id,           tab_pjpa.pppa_dp_flag AS pppa_dp_flag,           tab_pjpa.pppa_plnt_id AS pppa_plnt_id,           tab_pjpa.pjpr_is_leaf AS pjpr_is_leaf,           tab_pjpa.pjpr_project_type AS pjpr_project_type,           tab_pjpa.pjpr_project_ident AS pjpr_project_ident,           tab_pjpa.pjpr_pjpr_id AS parent_pjpr_id,           tab_pjpa.pjpr_lifecycle_number AS pjpr_lifecycle_number,           tab_pjpa.pjpr_mods_list AS pjpr_mods_list,           tab_pjpa.pjpr_short_description AS pjpr_short_description,           tab_pjpa.pjpr_version_count AS pjpr_version_count,           MAX(tab_pjpa.pppa_pppa_id) AS pppa_pppa_id,           MAX(tab_pjpa.pppa_new_part_plant) AS new_part_plant,           MAX(pppa_dev.pppa_new_part_global) AS new_part_global,           MAX(tab_pjpa.pppa_ctrl_r_plnt) AS ctrl_r_plnt,           tab_pjpa.pppa_part_master_id AS pppa_part_master_id,           MAX(pppa_dev.pppa_plan_dat_r) AS plan_dat_r,           MIN(tab_pjpa.pppa_added_manually) AS added_manually,           MIN(tab_pjpa.pppa_ctrl_r_plnt_mo_man) AS ctrl_r_plnt_mo_man,           MIN(pppa_dev.pppa_plan_dat_r_mo_man) AS plan_dat_r_mo_man,           MAX(tab_pjpa.pppa_creation_date) AS pppa_creation_date,           MAX(tab_pjpa.pppa_valid_until) AS pppa_valid_until,           MAX(tab_pjpa.pppa_added_timestamp) AS added_timestamp  FROM     S0NCSTR.S0NRP52Q006 as tab_pjpa  LEFT OUTER JOIN S0NCSTR.S0NRP52Q006 pppa_dev  ON pppa_dev.pjpr_pjpr_id = tab_pjpa.pjpr_pjpr_id     AND pppa_dev.pppa_part_id = tab_pjpa.pppa_part_id     AND pppa_dev.pppa_dp_flag = 'EP'  WHERE    1=1           AND (tab_pjpa.pjpr_project_ident = 'LK253X300MOLOCAL')               GROUP BY tab_pjpa.pppa_part_id, tab_pjpa.pppa_dp_flag, tab_pjpa.pppa_plnt_id,           tab_pjpa.pjpr_pjpr_id, tab_pjpa.pjpr_is_leaf, tab_pjpa.pjpr_project_type,           tab_pjpa.pjpr_project_ident, tab_pjpa.pjpr_lifecycle_number, tab_pjpa.pjpr_mods_list,           tab_pjpa.pjpr_short_description, tab_pjpa.pjpr_version_count, tab_pjpa.pppa_part_master_id    ) , sosc AS (  SELECT          TAB_SSPA.PART_NUMBER AS PART_NUMBER_INPUT,          TAB_SOSC.SOSC_ID,          TAB_SOSC.EINSTEIN_ID,          TAB_SOSC.SSC_NUMBER,          TAB_SOSC.SSPM_ID,          TAB_SOSC.NAME,          TAB_SOSC.IS_DELETED,          TAB_SOSC.LAST_CHANGE_EINST,          TAB_SOSC.IS_LEAD,          TAB_SOSC.SOURCING_REL,          TAB_SOSC.BASIC_TYPE_REL,          TAB_SOSC.ROADMAP_REL,          TAB_SOSC.CRS_RELEVANT,          TAB_SOSC.MAT_LEVEL_RISK,          TAB_SOSC.COMMONALITY_TYPE,          TAB_SOSC.PRODUCTION_COUNTRY,          TAB_SOSC.PROD_LOCATION,          TAB_SOSC.TIER_N,          TAB_SOSC.TCR,          TAB_SOSC.SOURCE_PACKAGE_NR,          TAB_SOSC.LOGISTICS_CONCEPT,          TAB_SOSC.MG_ID,          TAB_SOSC.MG_SHORT,          TAB_SOSC.MG_NAME,          TAB_SOSC.GCC_NAME,          TAB_SOSC.GCC_NUMBER,          TAB_SOSC.SUPPLIER_NUMBER,          TAB_SOSC.SUPPLIER_SHORT,          TAB_SOSC.SUPPLIER_INDEX,          TAB_SOSC.SUPPLIER_NAME,          TAB_SOSC.VALID_FROM,          TAB_SOSC.LUPD_PROCESS,          TAB_SOSC.LUPD_TIMESTAMP,          TAB_SOSC.LUPD_USER,          TAB_SOSC.VERSION_COUNT,       TAB_SOSC.VALID_UNTIL,          TAB_SOSC.IS_CURRENT_RECORD  FROM  